// Mensaje de prueba: confirma credencial de Telegram + chat ID + parse_mode HTML.
const { DateTime } = require('luxon');
const ahora = DateTime.now().setZone('Europe/Madrid');

const chatId = $env.TELEGRAM_CHAT_ID;
if (!chatId) {
  throw new Error('TELEGRAM_CHAT_ID esta vacio en .env. Ponelo y corre: docker compose up -d');
}

const mensaje = [
  '<b>Test de n8n</b>',
  '',
  'Si estas leyendo esto, funciona:',
  '- La credencial de Telegram esta bien configurada',
  '- El chat ID <code>' + chatId + '</code> es correcto',
  '- El formato HTML se renderiza',
  '',
  '<i>Enviado el ' + ahora.toFormat("dd/MM/yyyy 'a las' HH:mm:ss") + ' (Europe/Madrid)</i>',
].join('\n');

return [{ json: { mensaje, chatId } }];
